import assert from 'node:assert/strict';import {mkdir,writeFile} from 'node:fs/promises';import {chromium} from 'playwright';
const folder='diagnostics/rak-external-click-20261117',guide='https://www.rak.ae/wps/portal/rak/home/business/starting-business-rak-economic/key-steps-to-starting-a-business-in-ras-al-khaimah/';await mkdir(folder,{recursive:true});
const browser=await chromium.launch({headless:true,executablePath:process.env.HB_BROWSER_PATH}),report={runUrl:'https://github.com/hossambahr229-star/hossambahr-site/actions/runs/'+process.env.GITHUB_RUN_ID,scope:'Actual anonymous click/navigation initiation, not government execution',cases:[]};
try{for(const locale of ['ar','en']){const context=await browser.newContext({viewport:{width:1440,height:900}}),page=await context.newPage(),requests=[];context.on('request',r=>{if(r.isNavigationRequest())requests.push({url:r.url(),method:r.method()});});await page.goto('https://hossambahr.com'+(locale==='en'?'/en':'')+'/services/ras-al-khaimah-license-issuance/',{waitUntil:'networkidle'});const official=page.locator('#official-route'),before=page.url(),href=await official.getAttribute('href');assert.equal(href,guide);
const request=context.waitForEvent('request',{predicate:r=>r.isNavigationRequest()&&r.url().startsWith(guide),timeout:30000});await official.click();let observed,error;try{const r=await request;observed={url:r.url(),method:r.method()};}catch(e){error=String(e).slice(0,200);}const row={locale,before,href,observed,error,after:page.url(),requests};report.cases.push(row);await page.screenshot({path:folder+'/'+locale+'.jpg',type:'jpeg',quality:80});assert.ok(observed,'No actual navigation request after official button click: '+JSON.stringify(row));await context.close();}report.status='PASS';}catch(e){report.status='FAIL';report.error=String(e);throw e;}finally{await writeFile(folder+'/report.json',JSON.stringify(report,null,2));await browser.close();}console.log(JSON.stringify(report));